SourceCode.Declaration:
/// <summary>
/// The <c>AVAWHSProcessGuideDoCreateLicensePlaterStep</c> represents a step that create the license plate
/// </summary>
[
    ProcessGuideStepName(classStr(AVAWHSProcessGuideDoCreateLicensePlaterStep))
]
class AVAWHSProcessGuideDoCreateLicensePlaterStep extends ProcessGuideStepWithoutPrompt
{
}

Method.Source:
protected final void doExecute()
{
    WhsrfPassthrough    pass;
    WHSLicensePlate     licensePlate;

    pass = controller.parmSessionState().parmPass();

    super();

    if (pass.lookupStr(ProcessGuideDataTypeNames::AVALicensePlateId)
     && pass.lookupStr(ProcessGuideDataTypeNames::AVAContainerType))
    {
        licensePlate = WHSLicensePlate::createLicensePlate(pass.lookupStr(ProcessGuideDataTypeNames::AVALicensePlateId), true, pass.lookupStr(ProcessGuideDataTypeNames::AVAContainerType));

        pass.remove(ProcessGuideDataTypeNames::AVALicensePlateId);
        pass.insert(ProcessGuideDataTypeNames::AVASuccessMsg, strFmt("@NDX:AVALicencePlateCreated", licensePlate.LicensePlateId, licensePlate.ContainerTypeCode));
    }             
}
